// WinUlx3sTop.v -- ULX3S board top for the window hardware (WinUlx3s.bsv,
// mkWinUlx3s), docs/simpos/window_hardware_plan.md H3.  ALL OURS; the
// reset is PimmFepTop.v's (after Top.v).  Pins: ulx3s_win.lpf.
//
// The video PLL is `win_pll`, generated by bsv/run_win_fpga.sh into its
// build directory with
//     ecppll -n win_pll -i 25 -o 370 --clkout1 74 -f win_pll.v
// (mode 0, plan §5.2: CLKI_DIV 5, CLKFB_DIV 74, VCO 740 MHz, CLKOP / 2 =
// 370 MHz the shift clock, CLKOS / 10 = 74 MHz the pixel clock).
// 74.25 / 371.25 MHz, CEA-861's nominal clocks for VIC 34, are not on
// that VCO: `ecppll -i 25 -o 371.25 --clkout1 74.25` gives 370 and
// 82.22 MHz (run 2026-11-25), so the picture runs at 74 MHz, 29.9 Hz.
//
// The serializer's four lanes leave through ODDRX1F, D0 first then D1,
// as flute-lx50's Video_DVI.v does at 640x480.  The design is held in
// reset until the PLL locks and for 255 clocks after configuration;
// FIRE1 (BTN1) resets it.  H6 (2026-11-26): the host link on the FTDI
// UART (mkWinLink inside mkWinUlx3s); led[3] lights while the line in is low.
// H5: the PS/2 keyboard on US2 (bd_dp clock, bd_dn data); led[4] its clock low.
module ulx3s_win_top(
    input  wire       clk_25mhz,
    input  wire       BTN1,
    input  wire       ftdi_txd,     // the host's line in (M1)
    output wire       ftdi_rxd,     // the board's line out (L4)
    input  wire       usb_fpga_bd_dp,  // US2 D+: the PS/2 clock (D15)
    input  wire       usb_fpga_bd_dn,  // US2 D-: the PS/2 data (E15)
    output wire       usb_fpga_pu_dp,  // US2's pull-ups on (B12, C12)
    output wire       usb_fpga_pu_dn,
    output wire [7:0] led,
    output wire [3:0] gpdi_dp       // [0] blue, [1] green, [2] red, [3] clock
);
    wire sclk, pclk, locked;
    win_pll pll (.clkin(clk_25mhz), .clkout0(sclk), .clkout1(pclk), .locked(locked));

    reg [7:0] power_on_reset = 8'h00;
    always @(posedge clk_25mhz) begin
        if (BTN1 || !locked)
            power_on_reset <= 8'h00;
        else if (!&power_on_reset)
            power_on_reset <= power_on_reset + 1'b1;
    end
    wire rst_n = (&power_on_reset) & ~BTN1;

    wire [7:0] pins;
    wire [1:0] st;
    wire       blink;
    mkWinUlx3s win (
        .CLK(clk_25mhz),
        .RST_N(rst_n),
        .CLK_pclk(pclk),
        .CLK_sclk(sclk),
        .rxd(ftdi_txd),
        .txd(ftdi_rxd),
        .ps2_clk(usb_fpga_bd_dp),
        .ps2_dat(usb_fpga_bd_dn),
        .pins(pins),
        .led(st),
        .blink(blink)
    );

    genvar i;
    generate for (i = 0; i < 4; i = i + 1) begin : lane
        ODDRX1F ddr (.D0(pins[2 * i]), .D1(pins[2 * i + 1]), .SCLK(sclk), .RST(1'b0),
                     .Q(gpdi_dp[i]));
    end endgenerate

    assign led = {locked, 2'b0, ~usb_fpga_bd_dp, ~ftdi_txd, blink, st[1], st[0]};
    // the PS/2 lines are open-collector and idle high: US2's 1.5k pull-ups
    // on both (INFERENCE: the ULX3S's pu_dp/pu_dn drive them; unchecked)
    assign usb_fpga_pu_dp = 1'b1;
    assign usb_fpga_pu_dn = 1'b1;
endmodule
